import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

const root = createScene();
root.updateMatrixWorld(true);

// Bake world transforms into geometry, so scaling/rotation/position are preserved.
const exportRoot = new THREE.Group();
root.traverse((obj) => {
  if (obj.isMesh && obj.geometry) {
    let geom = obj.geometry.clone();
    geom.applyMatrix4(obj.matrixWorld);
    if (geom.index) geom = geom.toNonIndexed();
    if (!geom.attributes.normal) geom.computeVertexNormals();
    const m = new THREE.Mesh(geom);
    m.name = obj.name || 'mesh';
    exportRoot.add(m);
  }
});

// Convert Y-up to Z-up for Blender: apply -90 deg X-rotation.
const axisMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
exportRoot.children.forEach((child) => {
  child.geometry.applyMatrix4(axisMatrix);
});

const exporter = new OBJExporter();
const objString = exporter.parse(exportRoot);

const outPath = '/root/output/object.obj';
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, objString);
console.log(`Wrote ${outPath} (${objString.length} bytes)`);
